<script setup lang="ts">
import { LockKeyhole } from '@lucide/vue'
import type { Doctor } from '../domain/types'
import { formatHours, isSunday, monthDates, weekday } from '../domain/calendar'
import { clockLabel, planShifts, shiftHours, shiftStyle } from '../domain/shifts'
defineProps<{ doctors: Doctor[]; view: 'code' | 'time' | 'both' }>()
const emit = defineEmits<{ select: [doctor: Doctor, date: string] }>()
const w = useWorkspace()
const dates = computed(() => monthDates(w.activeMonth.value))
const shifts = computed(() => new Map(w.data.value && w.plan.value ? planShifts(w.data.value, w.plan.value).map(s => [s.code, s]) : []))
const summary = computed(() => new Map(w.summaries.value.map(s => [s.doctor.id, s])))
const rowIssues = computed(() => new Set(w.issues.value.filter(i => i.severity === 'error').map(i => `${i.doctorId}:${i.date}`)))
const getShift = (id: string, date: string) => shifts.value.get(w.plan.value?.assignments[id]?.[date] ?? '')
const editable = (date: string) => w.canEdit.value && !w.plan.value?.locked && Number(date.slice(-2)) > (w.plan.value?.frozenThrough ?? 0)
</script>
<template><div class="scrollbar-thin overflow-x-auto"><table class="roster-table w-full text-center"><thead><tr><th class="sticky-doctor min-w-44 px-4 py-4 text-left text-xs font-semibold">Dokter</th><th v-for="(date, i) in dates" :key="date" class="min-w-14 px-2 py-3" :class="[isSunday(date) ? 'bg-rose-50/70' : 'bg-slate-50', view !== 'code' ? 'min-w-25' : '']"><p class="text-xs font-normal" :class="isSunday(date) ? 'text-rose-400' : 'text-slate-600'">{{ weekday(date) }}</p><p class="mt-1 text-xs font-semibold" :class="isSunday(date) ? 'text-rose-600' : ''">{{ i + 1 }}</p><LockKeyhole v-if="!editable(date)" :size="9" class="mx-auto mt-1 text-slate-300"/></th><th class="min-w-20 bg-brand-50 px-3 py-3 text-xs font-semibold text-brand-800">Jam</th></tr></thead><tbody><tr v-for="(doctor, index) in doctors" :key="doctor.id"><th class="sticky-doctor px-4 py-4 text-left"><div class="flex items-center gap-2.5"><span class="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-slate-50 text-xs font-semibold text-slate-600">{{ index + 1 }}</span><div><p class="whitespace-nowrap text-xs font-semibold">{{ doctor.name }}</p><p class="mt-0.5 text-xs font-normal text-slate-600">{{ doctor.unit === 'anak' ? 'Ruang anak' : 'Rotasi layanan' }}</p></div></div></th><td v-for="date in dates" :key="date" class="p-1.5" :class="isSunday(date) ? 'bg-rose-50/20' : ''"><button class="roster-cell relative flex min-h-10 w-full flex-col items-center justify-center rounded-lg px-1.5 py-1.5 disabled:cursor-default" :class="shiftStyle(getShift(doctor.id, date))" :title="`${doctor.name} · ${date}: ${clockLabel(getShift(doctor.id, date))}`" :aria-label="`${doctor.name}, ${date}, ${w.plan.value?.assignments[doctor.id]?.[date] || 'belum diisi'}, ${clockLabel(getShift(doctor.id, date))}`" :disabled="!editable(date)" @click="emit('select', doctor, date)"><span v-if="view !== 'time'" class="whitespace-nowrap text-xs font-semibold">{{ w.plan.value?.assignments[doctor.id]?.[date] || '—' }}</span><span v-if="view !== 'code'" class="mt-0.5 text-[9px] leading-relaxed whitespace-nowrap">{{ clockLabel(getShift(doctor.id, date)) }}</span><span v-if="view === 'both'" class="mt-0.5 text-[9px] opacity-65">{{ getShift(doctor.id, date) ? `${formatHours(shiftHours(getShift(doctor.id, date)))} jam` : '' }}</span><span v-if="rowIssues.has(`${doctor.id}:${date}`)" class="absolute top-1 right-1 h-1.5 w-1.5 rounded-full bg-rose-500"/></button></td><td class="bg-brand-50/40 px-2 py-4 text-xs font-semibold tabular-nums text-brand-800">{{ formatHours(summary.get(doctor.id)?.totalHours ?? null) }}</td></tr><tr v-if="!doctors.length"><td :colspan="dates.length + 2" class="p-8 text-sm text-slate-600">Tidak ada dokter sesuai pencarian.</td></tr></tbody></table></div></template>
